#endif
}

static inline void align_put_bits(PutBitContext *s) /* <=== align_put_bits */ 
{
    put_bits(s, s->bit_left & 7, 0);
}

static inline int put_bits_count(PutBitContext *s) /* <=== put_bits_count */ 
{
    return (s->buf_ptr - s->buf) * 8 + BUF_BITS - s->bit_left;
}

static inline int init_get_bits_xe(GetBitContext *s, const uint8_t *buffer, /* <=== init_get_bits_xe */ 
                                   int bit_size, int is_le)
{
    int buffer_size;
    int ret = 0;

    if (bit_size >= INT_MAX - FFMAX(7, AV_INPUT_BUFFER_PADDING_SIZE*8) || bit_size < 0 || !buffer) {
        bit_size    = 0;
        buffer      = NULL;
        ret         = AVERROR_INVALIDDATA;
    }

    buffer_size = (bit_size + 7) >> 3;

    s->buffer             = buffer;
    s->size_in_bits       = bit_size;
